class Solution:
    def areSentencesSimilar(self, sentence1: str, sentence2: str) -> bool:
        a,b=sentence1.split(),sentence2.split()
        if len(a) < len(b): a,b=b,a
        n=len(a)
        for l in range(n+1):
            for r in range(l,n+1):
                if a[:l]+a[r:] == b: return True
        return False

